-- PT124-S2-Q1. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT124-S2-Q1$batch04$ AND q.stimulus=$batch04$The water of Lake Laberge, in Canada, currently contains high levels of the pesticide toxaphene. Authorities are puzzled because toxaphene was banned in North America in the early 1980s and now is used only in a few other parts of the world.$batch04$ AND q.prompt=$batch04$Which one of the following, if true, does most to explain why the water of Lake Laberge currently contains high levels of toxaphene?$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT124-S2-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT124-S2-Q1$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT124-S2-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT124-S2-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Toxaphene was banned in North America in the early 1980s and is now used only in a few other parts of the world.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Lake Laberge, in Canada, has high levels of toxaphene today?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Two ways the pesticide could be there. It could have arrived recently from somewhere it is still used, or it could be left over from before the ban. Either story resolves the puzzle.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a source: old toxaphene that never went away, or new toxaphene arriving from elsewhere.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT124-S2-Q1$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Pesticide levels often stay high for decades after use ends. The ban was only a few decades ago, so the toxaphene in the lake can simply be left over from before it.$batch04$), ($batch04$B$batch04$, $batch04$Other pesticides in the water do not explain where the toxaphene came from.$batch04$), ($batch04$C$batch04$, $batch04$If toxic chemicals rarely travel far through the air, toxaphene from distant countries is less likely to reach the lake. This closes off one explanation.$batch04$), ($batch04$D$batch04$, $batch04$Manufacturers opposing the ban does not mean anyone kept using toxaphene after it.$batch04$), ($batch04$E$batch04$, $batch04$The puzzle is toxaphene in the lake's water. How easily it is detected in fish says nothing about why it is there.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT124-S2-Q1$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
